insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('d-readiness-map-is-not-settled-s709','decision','The re-mint readiness gate: the subject map alone settles no member','S709, Sam''s to revise: kb/_mid_readiness.py counts a member settled only by a person''s save for its college''s code (noncredit under its own category) or a person''s statewide filing. The subject map is a draft, shown beside a held member; it is the map that gave 45 shared M-IDs an ELEC prefix from AED.',array['commons','subjects','m-id','remint'],'proposed','S709 session, #3697',null,null,'SkyMurrelet (S709)','2026-11-22'),
('f-aed-scope-is-127-mids-s709','fact','The AED re-mint scope is 127 M-IDs, 34 ready by the draft gate','S709: read from unified_courses_members.js (2026-11-22), the M-IDs holding a Cerritos AED course are 127 (120 ELEC), 3,084 members; S707''s 46 came from the May preview kb/coci_minted_memberships.json. 34 pass the draft gate, all Cerritos noncredit settled to VOCE. kb/status/mid_readiness.json.',array['commons','subjects','m-id','remint'],'proposed','kb/status/mid_readiness.json, #3697',null,null,'SkyMurrelet (S709)','2026-11-22'),
('f-uncategorized-noncredit-takes-no-code-s709','fact','A noncredit course with no category in the export cannot take a common code','S709: subject_decisions refuses a code on nc:uncategorized, since that band has no noncredit MQ discipline. 120 AED-scope members (Cerritos AED 26, NOCE ESLA 42 and others) sit there, so the readiness gate holds them as "no noncredit category" until the export names one or the rule changes.',array['commons','subjects','noncredit','remint'],'proposed','kb/_mid_readiness.py on main data, #3697',null,null,'SkyMurrelet (S709)','2026-11-22'),
('d-compare-json-gzip-over-limit-s709','decision','The outcomes compare writes its JSON gzipped past the 5 MB file limit','S709: kb/_mid_outcomes_compare.py on 45,673 rows wrote 8.6 MB, over scripts/repo_size_guard.py FILE_CAP_MB. Past 5 MB it now writes .json.gz (0.9 MB); kb/_mid_readiness.py reads either. The compare is not nightly: when reads grow past it, every M-ID holds on the outcomes test until a session reruns it.',array['commons','m-id','remint','repo-size'],'proposed','S709 session, #3697',null,null,'SkyMurrelet (S709)','2026-11-22')
on conflict (slug) do nothing;
